// Valida lo que manda el back (POST /api/hoteles/buscar-externo). El back
// ya resolvió el destino del catálogo: acá llegan su id y su IATA reales.
// Antes el IATA se inventaba con las 3 primeras letras de la ciudad y el
// bulk descartaba todos los hoteles porque ese destino no existía.
const b = $input.first().json.body || {};
const faltan = ['destinoId', 'destinoNombre', 'checkin', 'checkout'].filter((k) => !b[k]);
if (faltan.length) {
  return [{ json: { ok: false, mensaje: `Faltan datos para buscar: ${faltan.join(', ')}` } }];
}
if (!$env.RAPIDAPI_KEY) {
  return [{ json: { ok: false, mensaje: 'Falta la variable RAPIDAPI_KEY en el servicio de n8n.' } }];
}
return [{ json: {
  ok: true,
  destinoId: b.destinoId,
  destinoIATA: b.destinoIATA || null,
  // Booking busca mejor sin aclaraciones entre paréntesis ("Madrid (MAD)").
  destinoNombre: String(b.destinoNombre).replace(/\s*\(.*?\)\s*/g, ' ').trim(),
  checkin: b.checkin,
  checkout: b.checkout,
  adults: Number(b.adults) || 2,
  rooms: Number(b.rooms) || 1,
  estrellasMin: b.estrellasMin ? Number(b.estrellasMin) : null,
  precioMax: b.precioMax ? Number(b.precioMax) : null,
} }];

// searchDestination devuelve ciudades, barrios, aeropuertos y hoteles
// mezclados. Se prefiere la ciudad, y se usa el search_type que informa
// Booking para ese resultado (antes iba siempre "CITY", y si el primer
// resultado era un aeropuerto la búsqueda de hoteles volvía vacía).
const raw = $input.first().json;
const ctx = $('Parsear input').first().json;
if (raw && raw.status === false) {
  return [{ json: { ok: false, mensaje: `Booking rechazó la búsqueda del destino: ${raw.message || 'sin detalle'}` } }];
}
const lista = Array.isArray(raw?.data) ? raw.data : [];
const tipo = (d) => String(d.search_type || d.dest_type || '').toLowerCase();
const elegido = lista.find((d) => tipo(d) === 'city') || lista.find((d) => ['region', 'district'].includes(tipo(d))) || lista[0];
if (!elegido || !elegido.dest_id) {
  return [{ json: { ok: false, mensaje: `Booking no encontró "${ctx.destinoNombre}". Probá con el nombre de la ciudad en otro idioma (ej. "Rome").` } }];
}
return [{ json: { ...ctx, destId: String(elegido.dest_id), searchType: tipo(elegido).toUpperCase() || 'CITY', destinoBooking: elegido.label || elegido.name || ctx.destinoNombre } }];

// Booking devuelve el precio TOTAL de la estadía: se pasa a precio por
// noche. Los filtros de estrellas y precio se aplican acá, sobre el dato ya
// normalizado, en vez de mandarlos a la API (antes iban vacíos cuando no se
// usaban y la API podía devolver cero resultados).
const raw = $input.first().json;
const ctx = $('Elegir destino').first().json;
if (raw && raw.status === false) {
  return [{ json: { ok: false, mensaje: `Booking rechazó la búsqueda de hoteles: ${raw.message || 'sin detalle'}` } }];
}
const hoteles = Array.isArray(raw?.data?.hotels) ? raw.data.hotels : [];
const noches = Math.max(1, Math.round((new Date(ctx.checkout) - new Date(ctx.checkin)) / 86400000));

const items = [];
for (const h of hoteles) {
  const p = h.property || {};
  const nombre = (p.name || h.hotel_name || '').trim();
  if (!nombre) continue;
  const total = Number(p.priceBreakdown?.grossPrice?.value ?? h.min_total_price ?? 0);
  const precioNoche = Math.round((total / noches) * 100) / 100;
  const clase = Math.round(Number(p.accuratePropertyClass || p.propertyClass || 0));
  const foto = Array.isArray(p.photoUrls) ? p.photoUrls[0] : null;
  const rating = p.reviewScore != null ? Math.round(Number(p.reviewScore) * 10) / 10 : null;

  if (ctx.estrellasMin && clase && clase < ctx.estrellasMin) continue;
  if (ctx.precioMax && precioNoche > ctx.precioMax) continue;

  items.push({
    nombre,
    destinoId: ctx.destinoId,
    destinoIATA: ctx.destinoIATA,
    // Sin categoría informada, la columna no admite nulo: queda en 3 como
    // en el alta manual.
    estrellas: clase >= 1 && clase <= 5 ? clase : 3,
    precioNoche,
    moneda: p.priceBreakdown?.grossPrice?.currency || 'USD',
    rating,
    // La miniatura que manda Booking es de 60 px: se pide una de 500.
    urlImagen: foto ? String(foto).replace(/\/square\d+\//, '/max500/') : null,
    urlReserva: `https://www.booking.com/searchresults.html?ss=${encodeURIComponent(nombre + ' ' + ctx.destinoNombre)}&checkin=${ctx.checkin}&checkout=${ctx.checkout}&group_adults=${ctx.adults}&no_rooms=${ctx.rooms}`,
    direccion: p.wishlistName || null,
    fuente: 'BOOKING',
  });
  if (items.length >= 15) break;
}

if (!items.length) {
  const filtros = ctx.estrellasMin || ctx.precioMax ? ' con esos filtros' : '';
  return [{ json: { ok: false, mensaje: `Booking no devolvió hoteles disponibles en ${ctx.destinoBooking} para esas fechas${filtros}.`, encontrados: hoteles.length } }];
}
return [{ json: { ok: true, items, encontrados: hoteles.length } }];

const bulk = $json;
const norm = $('Normalizar hoteles').first().json;
return [{ json: {
  ok: true,
  encontrados: norm.encontrados,
  creados: bulk.creados ?? 0,
  actualizados: bulk.actualizados ?? 0,
  descartados: bulk.descartados ?? 0,
} }];

// Salida de error de un nodo HTTP (Booking o el back). Se arma un mensaje
// legible para el panel en vez de dejar que la ejecución muera sin
// responder al webhook (el front veía un 500 sin explicación).
const e = $json.error;
const msg = typeof e === 'string' ? e : (e?.message || $json.message || JSON.stringify($json).slice(0, 200));
let pista = '';
if (/403|not subscribed/i.test(msg)) pista = ' (¿la RAPIDAPI_KEY está suscripta a booking-com15?)';
else if (/429|quota|rate/i.test(msg)) pista = ' (se agotó la cuota de RapidAPI)';
else if (/401/.test(msg)) pista = ' (revisá N8N_API_KEY en n8n y en el back)';
return { json: { ok: false, mensaje: `${msg}${pista}`.slice(0, 400) } };
